package com.mahweb.mahyarnfc.omnishare.transport;
import java.io.*; import java.nio.charset.StandardCharsets; import java.util.Arrays;
public final class DeliveryAck { public final String transferId,recipientDeviceId; public final long receivedAtEpochMs; public final byte[] signature; public DeliveryAck(String t,String r,long at,byte[] s){transferId=t;recipientDeviceId=r;receivedAtEpochMs=at;signature=s==null?new byte[0]:Arrays.copyOf(s,s.length);} public DeliveryAck withSignature(byte[] s){return new DeliveryAck(transferId,recipientDeviceId,receivedAtEpochMs,s);} public byte[] unsignedBytes(){try{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);ws(d,transferId);ws(d,recipientDeviceId);d.writeLong(receivedAtEpochMs);d.flush();return b.toByteArray();}catch(IOException e){throw new IllegalStateException(e);}} private static void ws(DataOutputStream d,String s)throws IOException{byte[]b=(s==null?"":s).getBytes(StandardCharsets.UTF_8);d.writeInt(b.length);d.write(b);} }
